// Shared kernel: Vietnam's two-level administrative divisions (tỉnh/thành → phường/xã), as in force since
// 01/07/2025. Data is generated by `npm run build:address` into shared/data/address (see the script header).
import provincesData from "../data/address/provinces.json"

export type ProvinceKind = "city" | "province"

export type Province = {
  /** Two-digit code, e.g. "79" for TP. Hồ Chí Minh. */
  code: string
  /** Bare name without the “Thành phố” prefix, e.g. "Hồ Chí Minh". */
  name: string
  kind: ProvinceKind
}

export type Ward = {
  /** Five-digit commune code. */
  code: string
  /** Full name with its type, e.g. "Phường An Phú Đông", "Xã Thạnh An", "Đặc khu Cô Tô". */
  name: string
}

export const provinces: readonly Province[] = provincesData as Province[]

/** How the site writes a province: “TP. Hồ Chí Minh” for the six cities, plain name for provinces. */
export const provinceLabel = (p: Province) => (p.kind === "city" ? `TP. ${p.name}` : p.name)

export const provinceLabels: readonly string[] = provinces.map(provinceLabel)

export const findProvince = (code: string): Province | undefined => provinces.find((p) => p.code === code)

export const findProvinceByLabel = (label: string): Province | undefined => provinces.find((p) => provinceLabel(p) === label)

/** Loads the wards of one province on demand (one small JSON chunk per province, ~10 KB for HCM). */
export async function loadWards(provinceCode: string): Promise<Ward[]> {
  if (!findProvince(provinceCode)) return []
  const mod = await import(`../data/address/wards/${provinceCode}.json`)
  return mod.default as Ward[]
}

export async function findWard(provinceCode: string, wardCode: string): Promise<Ward | undefined> {
  return (await loadWards(provinceCode)).find((w) => w.code === wardCode)
}

/** Lowercase, strip Vietnamese diacritics (đ → d): lets “an phu dong” find “Phường An Phú Đông”. */
export function searchKey(s: string): string {
  return s.normalize("NFD").replace(/\p{Diacritic}/gu, "").replace(/đ/gi, "d").toLowerCase()
}
